mapper.select:
SELECT COUNT(*)
FROM TB_PM07M01
WHERE 1=1

AND ST_DT <= #{reqDtTo}
AND ED_DT >= #{reqDtFrom}


AND VAC_TYPE_CD = #{vacTypeCd}


AND SANCTN_STS = #{sanctnSts}


AND REQ_ID = #{reqId}


AND (EXISTS (SELECT 1 FROM TB_CM06M01 U WHERE U.ID = TB_PM07M01.REQ_ID AND U.NAME LIKE '%' || #{reqIdNm} || '%') OR REQ_TITL LIKE '%' || #{reqIdNm} || '%' OR REQ_ID LIKE '%' || #{reqIdNm} || '%')


AND REQ_DEPT_ID = #{reqDeptId}


AND EXISTS (SELECT 1 FROM TB_CM04M01 D WHERE D.DEPT_ID = TB_PM07M01.REQ_DEPT_ID AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%')

SELECT M.CO_CD, M.REQ_NO, M.REQ_DT, M.REQ_TITL, M.REQ_ID, M.REQ_DEPT_ID, M.VAC_TYPE_CD, C1.CODE_NM AS VAC_TYPE_NM, U.NAME AS REQ_ID_NM, D.DEPT_NM AS REQ_DEPT_NM, U.SALES_AREA AS REQ_SALES_AREA, M.AMPM_CD, C2.CODE_NM AS AMPM_NM, TO_CHAR(TO_DATE(M.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(M.ED_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, M.ST_DT AS RAW_ST_DT, M.ED_DT AS RAW_ED_DT, TO_CHAR(TO_DATE(M.ST_TM, 'HH24MI'), 'HH24:MI') AS ST_TM, TO_CHAR(TO_DATE(M.ED_TM, 'HH24MI'), 'HH24:MI') AS ED_TM, M.VAC_DAYS, M.DEDUCT_DAYS, M.REQ_RMK, NVL(W.CALC_SANCTN_STS, NVL(M.SANCTN_STS, 'TEMP')) AS SANCTN_STS, M.WORK_RPT_YN, M.CREAT_ID, TO_CHAR(M.CREAT_DTTM, 'YYYY-MM-DD HH24:MI:SS') AS CREAT_DTTM FROM TB_PM07M01 M LEFT OUTER JOIN TB_CM06M01 U ON M.REQ_ID = U.ID LEFT OUTER JOIN TB_CM04M01 D ON M.REQ_DEPT_ID = D.DEPT_ID LEFT OUTER JOIN TB_CM05M01 C1 ON M.VAC_TYPE_CD = C1.CODE_ID LEFT OUTER JOIN TB_CM05M01 C2 ON M.AMPM_CD = C2.CODE_ID LEFT OUTER JOIN ( SELECT TODO_NO, CASE WHEN SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND (SANCTN_STTUS = 'N' OR SANCTN_STTUS = 'R' OR SANCTN_STTUS = '4') THEN 1 ELSE 0 END) > 0 THEN 'RTN' WHEN COUNT(TODO_KEY) = 0 THEN 'TEMP' WHEN COUNT(TODO_KEY) > 0 AND COUNT(TODO_KEY) = SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) THEN 'END' WHEN SUM(CASE WHEN SANCTN_SN > 1 AND TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) > 0 THEN 'ING' ELSE 'REQ' END AS CALC_SANCTN_STS FROM TB_WB20M03 WHERE TODO_DIV1_CODE_ID = 'TODODIV20' GROUP BY TODO_NO ) W ON M.REQ_NO = W.TODO_NO WHERE 1=1
AND M.ST_DT <= #{reqDtTo} AND M.ED_DT >= #{reqDtFrom}
AND M.VAC_TYPE_CD = #{vacTypeCd}
AND M.REQ_ID = #{reqId}
AND (U.NAME LIKE '%' || #{reqIdNm} || '%' OR M.REQ_TITL LIKE '%' || #{reqIdNm} || '%' OR M.REQ_ID LIKE '%' || #{reqIdNm} || '%')
AND M.REQ_DEPT_ID = #{reqDeptId}
AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%'
AND NVL(W.CALC_SANCTN_STS, NVL(M.SANCTN_STS, 'TEMP')) = #{sanctnSts}
ORDER BY M.ST_DT ASC, M.REQ_NO ASC

SELECT * FROM ( SELECT M.CO_CD, M.REQ_NO, M.REQ_ID, M.REQ_DEPT_ID, M.VAC_TYPE_CD, C1.CODE_NM AS VAC_TYPE_NM, U.NAME AS REQ_ID_NM, D.DEPT_NM AS REQ_DEPT_NM, M.AMPM_CD, C2.CODE_NM AS AMPM_NM, TO_CHAR(TO_DATE(M.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(M.ED_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, M.ST_DT AS RAW_ST_DT, M.ED_DT AS RAW_ED_DT, M.REQ_RMK, NVL(W.CALC_SANCTN_STS, NVL(M.SANCTN_STS, 'TEMP')) AS SANCTN_STS, 'VACATION' AS SRC_TYPE, 'VACATION' AS DOC_TYPE, M.REQ_NO AS DOC_NO FROM TB_PM07M01 M LEFT OUTER JOIN TB_CM06M01 U ON M.REQ_ID = U.ID LEFT OUTER JOIN TB_CM04M01 D ON M.REQ_DEPT_ID = D.DEPT_ID LEFT OUTER JOIN TB_CM05M01 C1 ON M.VAC_TYPE_CD = C1.CODE_ID LEFT OUTER JOIN TB_CM05M01 C2 ON M.AMPM_CD = C2.CODE_ID LEFT OUTER JOIN ( SELECT TODO_NO, CASE WHEN SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND (SANCTN_STTUS = 'N' OR SANCTN_STTUS = 'R' OR SANCTN_STTUS = '4') THEN 1 ELSE 0 END) > 0 THEN 'RTN' WHEN COUNT(TODO_KEY) = 0 THEN 'TEMP' WHEN COUNT(TODO_KEY) > 0 AND COUNT(TODO_KEY) = SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) THEN 'END' WHEN SUM(CASE WHEN SANCTN_SN > 1 AND TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) > 0 THEN 'ING' ELSE 'REQ' END AS CALC_SANCTN_STS FROM TB_WB20M03 WHERE TODO_DIV1_CODE_ID = 'TODODIV20' GROUP BY TODO_NO ) W ON M.REQ_NO = W.TODO_NO WHERE 1=1
AND M.ST_DT <= #{reqDtTo} AND M.ED_DT >= #{reqDtFrom}
AND M.VAC_TYPE_CD = #{vacTypeCd}
AND M.REQ_ID = #{reqId}
AND (U.NAME LIKE '%' || #{reqIdNm} || '%' OR M.REQ_TITL LIKE '%' || #{reqIdNm} || '%' OR M.REQ_ID LIKE '%' || #{reqIdNm} || '%')
AND M.REQ_DEPT_ID = #{reqDeptId}
AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%'
AND NVL(W.CALC_SANCTN_STS, NVL(M.SANCTN_STS, 'TEMP')) = #{sanctnSts}
UNION ALL
SELECT RM.CO_CD, RPT.TRIP_RPT_NO || '_' || D.SEQ AS REQ_NO, D.USER_ID AS REQ_ID, NULL AS REQ_DEPT_ID, NULL AS VAC_TYPE_CD, '출장' AS VAC_TYPE_NM, D.USER_NM AS REQ_ID_NM, D.DEPT_NM AS REQ_DEPT_NM, NULL AS AMPM_CD, NULL AS AMPM_NM, TO_CHAR(TO_DATE(SUBSTR(D.TRIP_ST_DTM, 1, 8), 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(SUBSTR(D.TRIP_ED_DTM, 1, 8), 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, SUBSTR(D.TRIP_ST_DTM, 1, 8) AS RAW_ST_DT, SUBSTR(D.TRIP_ED_DTM, 1, 8) AS RAW_ED_DT, RM.TRIP_PLACE AS REQ_RMK, NVL(WT.CALC_SANCTN_STS, 'TEMP') AS SANCTN_STS, 'TRIP' AS SRC_TYPE, 'TRIP_RPT' AS DOC_TYPE, RPT.TRIP_RPT_NO AS DOC_NO FROM TB_PM52M01 RPT JOIN TB_PM52D02 D ON D.TRIP_RPT_NO = RPT.TRIP_RPT_NO JOIN TB_PM51M01 RM ON RM.TRIP_REQ_NO = RPT.TRIP_REQ_NO LEFT OUTER JOIN ( SELECT TODO_NO, CASE WHEN SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND (SANCTN_STTUS = 'N' OR SANCTN_STTUS = 'R' OR SANCTN_STTUS = '4') THEN 1 ELSE 0 END) > 0 THEN 'RTN' WHEN COUNT(TODO_KEY) = 0 THEN 'TEMP' WHEN COUNT(TODO_KEY) > 0 AND COUNT(TODO_KEY) = SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) THEN 'END' WHEN SUM(CASE WHEN SANCTN_SN > 1 AND TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) > 0 THEN 'ING' ELSE 'REQ' END AS CALC_SANCTN_STS FROM TB_WB20M03 WHERE TODO_DIV1_CODE_ID = 'TODODIV20' AND TODO_DIV2_CODE_ID = 'TODODIV2200' GROUP BY TODO_NO ) WT ON WT.TODO_NO = RPT.TRIP_RPT_NO WHERE 1=1
AND SUBSTR(D.TRIP_ST_DTM, 1, 8) <= #{reqDtTo} AND SUBSTR(D.TRIP_ED_DTM, 1, 8) >= #{reqDtFrom}
AND D.USER_ID = #{reqId}
AND (D.USER_NM LIKE '%' || #{reqIdNm} || '%' OR D.USER_ID LIKE '%' || #{reqIdNm} || '%')
AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%'
UNION ALL
SELECT RM.CO_CD, RM.TRIP_REQ_NO || '_' || D.SEQ AS REQ_NO, D.USER_ID AS REQ_ID, NULL AS REQ_DEPT_ID, NULL AS VAC_TYPE_CD, '출장' AS VAC_TYPE_NM, D.USER_NM AS REQ_ID_NM, D.DEPT_NM AS REQ_DEPT_NM, NULL AS AMPM_CD, NULL AS AMPM_NM, TO_CHAR(TO_DATE(SUBSTR(D.TRIP_ST_DTM, 1, 8), 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(SUBSTR(D.TRIP_ED_DTM, 1, 8), 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, SUBSTR(D.TRIP_ST_DTM, 1, 8) AS RAW_ST_DT, SUBSTR(D.TRIP_ED_DTM, 1, 8) AS RAW_ED_DT, RM.TRIP_PLACE AS REQ_RMK, NVL(WT.CALC_SANCTN_STS, 'TEMP') AS SANCTN_STS, 'TRIP' AS SRC_TYPE, 'TRIP_REQ' AS DOC_TYPE, RM.TRIP_REQ_NO AS DOC_NO FROM TB_PM51M01 RM JOIN TB_PM51D01 D ON D.TRIP_REQ_NO = RM.TRIP_REQ_NO LEFT OUTER JOIN ( SELECT TODO_NO, CASE WHEN SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND (SANCTN_STTUS = 'N' OR SANCTN_STTUS = 'R' OR SANCTN_STTUS = '4') THEN 1 ELSE 0 END) > 0 THEN 'RTN' WHEN COUNT(TODO_KEY) = 0 THEN 'TEMP' WHEN COUNT(TODO_KEY) > 0 AND COUNT(TODO_KEY) = SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) THEN 'END' WHEN SUM(CASE WHEN SANCTN_SN > 1 AND TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) > 0 THEN 'ING' ELSE 'REQ' END AS CALC_SANCTN_STS FROM TB_WB20M03 WHERE TODO_DIV1_CODE_ID = 'TODODIV20' AND TODO_DIV2_CODE_ID = 'TODODIV2190' GROUP BY TODO_NO ) WT ON WT.TODO_NO = RM.TRIP_REQ_NO WHERE NOT EXISTS (SELECT 1 FROM TB_PM52M01 R2 WHERE R2.TRIP_REQ_NO = RM.TRIP_REQ_NO)
AND SUBSTR(D.TRIP_ST_DTM, 1, 8) <= #{reqDtTo} AND SUBSTR(D.TRIP_ED_DTM, 1, 8) >= #{reqDtFrom}
AND D.USER_ID = #{reqId}
AND (D.USER_NM LIKE '%' || #{reqIdNm} || '%' OR D.USER_ID LIKE '%' || #{reqIdNm} || '%')
AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%'
UNION ALL
SELECT M.CO_CD, M.REQ_NO, M.REQ_ID, M.DEPT_ID AS REQ_DEPT_ID, NULL AS VAC_TYPE_CD, '대체근무' AS VAC_TYPE_NM, NVL(U.NAME, M.REQ_NM) AS REQ_ID_NM, NVL(M.DEPT_NM, D.DEPT_NM) AS REQ_DEPT_NM, NULL AS AMPM_CD, NULL AS AMPM_NM, TO_CHAR(TO_DATE(M.HOLIDAY_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(M.HOLIDAY_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, M.HOLIDAY_DT AS RAW_ST_DT, M.HOLIDAY_DT AS RAW_ED_DT, M.SPECIAL_REASON AS REQ_RMK, NVL(WP.CALC_SANCTN_STS, 'TEMP') AS SANCTN_STS, 'SUBST' AS SRC_TYPE, 'SUBST' AS DOC_TYPE, M.REQ_NO AS DOC_NO FROM TB_PM08M01 M LEFT OUTER JOIN TB_CM06M01 U ON U.ID = M.REQ_ID LEFT OUTER JOIN TB_CM04M01 D ON D.DEPT_ID = M.DEPT_ID LEFT OUTER JOIN ( SELECT TODO_NO, CASE WHEN SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND (SANCTN_STTUS = 'N' OR SANCTN_STTUS = 'R' OR SANCTN_STTUS = '4') THEN 1 ELSE 0 END) > 0 THEN 'RTN' WHEN COUNT(TODO_KEY) = 0 THEN 'TEMP' WHEN COUNT(TODO_KEY) > 0 AND COUNT(TODO_KEY) = SUM(CASE WHEN TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) THEN 'END' WHEN SUM(CASE WHEN SANCTN_SN > 1 AND TODO_CF_DT IS NOT NULL AND SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) > 0 THEN 'ING' ELSE 'REQ' END AS CALC_SANCTN_STS FROM TB_WB20M03 WHERE TODO_DIV1_CODE_ID = 'TODODIV20' AND TODO_DIV2_CODE_ID = 'TODODIV2410' GROUP BY TODO_NO ) WP ON WP.TODO_NO = M.REQ_NO WHERE 1=1
AND M.HOLIDAY_DT <= #{reqDtTo} AND M.HOLIDAY_DT >= #{reqDtFrom}
AND M.REQ_ID = #{reqId}
AND (U.NAME LIKE '%' || #{reqIdNm} || '%' OR M.REQ_NM LIKE '%' || #{reqIdNm} || '%' OR M.REQ_ID LIKE '%' || #{reqIdNm} || '%')
AND M.DEPT_ID = #{reqDeptId}
AND NVL(M.DEPT_NM, D.DEPT_NM) LIKE '%' || #{reqDeptNm} || '%'
) UT ORDER BY UT.ST_DT ASC, UT.REQ_NO ASC

SELECT * FROM ( SELECT ROWNUM AS RNUM, T.* FROM ( SELECT M.CO_CD, M.REQ_NO, M.REQ_DT, M.REQ_TITL, M.REQ_ID, M.REQ_DEPT_ID, M.VAC_TYPE_CD, C1.CODE_NM AS VAC_TYPE_NM, NVL(U.NAME, M.REQ_TITL) AS REQ_ID_NM, D.DEPT_NM AS REQ_DEPT_NM, M.AMPM_CD, TO_CHAR(TO_DATE(M.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(M.ED_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, TO_CHAR(TO_DATE(M.ST_TM, 'HH24MI'), 'HH24:MI') AS ST_TM, TO_CHAR(TO_DATE(M.ED_TM, 'HH24MI'), 'HH24:MI') AS ED_TM, M.VAC_DAYS, M.DEDUCT_DAYS, M.REQ_RMK, M.MNG_RMK, NVL(M.SANCTN_STS, 'TEMP') AS SANCTN_STS, M.WORK_RPT_YN, M.CREAT_ID, TO_CHAR(M.CREAT_DTTM, 'YYYY-MM-DD HH24:MI:SS') AS CREAT_DTTM FROM TB_PM07M01 M LEFT JOIN TB_CM06M01 U ON U.ID = M.REQ_ID LEFT JOIN TB_CM04M01 D ON D.DEPT_ID = M.REQ_DEPT_ID LEFT JOIN TB_CM05M01 C1 ON C1.CODE_ID = M.VAC_TYPE_CD WHERE 1=1
AND M.ST_DT <= #{reqDtTo} AND M.ED_DT >= #{reqDtFrom}
AND M.VAC_TYPE_CD = #{vacTypeCd}
AND M.REQ_ID = #{reqId}
AND (U.NAME LIKE '%' || #{reqIdNm} || '%' OR M.REQ_TITL LIKE '%' || #{reqIdNm} || '%' OR M.REQ_ID LIKE '%' || #{reqIdNm} || '%')
AND M.REQ_DEPT_ID = #{reqDeptId}
AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%'
AND M.SANCTN_STS = #{sanctnSts}
ORDER BY D.DEPT_NM ASC, U.NAME ASC, M.ST_DT DESC, M.REQ_NO DESC ) T
WHERE ROWNUM <= #{lastIndex}
)
WHERE RNUM >= #{firstIndex}

SELECT COUNT(*)
FROM TB_PM07M02
WHERE CO_CD = #{coCd} AND YY = #{yy} AND USER_ID = #{userId}

SELECT T.CO_CD, T.YY, T.USER_ID, T.USER_NM, T.DEPT_NM, T.ENTER_DT, T.LEAVE_DT, T.GRANT_DAYS, T.USED_DAYS, (T.GRANT_DAYS - T.USED_DAYS) AS BALANCE_DAYS, T.WORK_SUBST_DAYS, T.WORK_SUBST_USED_DAYS, (T.WORK_SUBST_DAYS - T.WORK_SUBST_USED_DAYS) AS WORK_SUBST_BALANCE_DAYS, T.SUMMER_VAC_DAYS, T.SUMMER_VAC_USED_DAYS, (T.SUMMER_VAC_DAYS - T.SUMMER_VAC_USED_DAYS) AS SUMMER_VAC_BALANCE_DAYS, T.AUTO_YN, T.RMK, T.VAC_INFO_LIST, T.VAC_ANNUAL_INFO_LIST, T.VAC_WORK_SUBST_INFO_LIST, T.VAC_SUMMER_INFO_LIST FROM ( SELECT M.CO_CD, M.YY, M.USER_ID, U.NAME AS USER_NM, D.DEPT_NM, NVL(D.SORT_NO, 9999) AS DEPT_SORT_NO, TO_CHAR(U.ENTER_DT, 'YYYY-MM-DD') AS ENTER_DT, TO_CHAR(U.LEAVE_DT, 'YYYY-MM-DD') AS LEAVE_DT, NVL(M.GRANT_DAYS, 0) AS GRANT_DAYS, NVL(M.WORK_SUBST_DAYS, 0) AS WORK_SUBST_DAYS, NVL(M.SUMMER_VAC_DAYS, 0) AS SUMMER_VAC_DAYS, NVL(VS.USED_DAYS, 0) AS USED_DAYS, NVL(VS.WORK_SUBST_USED_DAYS, 0) AS WORK_SUBST_USED_DAYS, NVL(VS.SUMMER_VAC_USED_DAYS, 0) AS SUMMER_VAC_USED_DAYS, VS.VAC_INFO_LIST, VS.VAC_ANNUAL_INFO_LIST, VS.VAC_WORK_SUBST_INFO_LIST, VS.VAC_SUMMER_INFO_LIST, M.AUTO_YN, M.RMK FROM TB_PM07M02 M LEFT OUTER JOIN TB_CM06M01 U ON M.USER_ID = U.ID LEFT OUTER JOIN TB_CM04M01 D ON D.DEPT_ID = SUBSTR(NVL(U.VIEW_DEPT_ID, U.DEPT_ID), 1, 5) /* 휴가 신청실적 단일 집계 인라인 뷰 조인 (I/O 병목 및 서브쿼리 N*4회 반복실행 100% 제거) */ LEFT OUTER JOIN ( SELECT V.CO_CD, V.REQ_ID, SUM(CASE WHEN V.VAC_TYPE_CD IN ('PM07TYPE01','PM07TYPE02') THEN V.DEDUCT_DAYS ELSE 0 END) AS USED_DAYS, SUM(CASE WHEN V.VAC_TYPE_CD IN ('PM07TYPE11','PM07TYPE12') THEN V.DEDUCT_DAYS ELSE 0 END) AS WORK_SUBST_USED_DAYS, SUM(CASE WHEN V.VAC_TYPE_CD = 'PM07TYPE09' THEN V.DEDUCT_DAYS ELSE 0 END) AS SUMMER_VAC_USED_DAYS, /* 1. 년차휴가 전용 이력 */ LISTAGG( CASE WHEN V.VAC_TYPE_CD IN ('PM07TYPE01','PM07TYPE02') THEN TO_CHAR(TO_DATE(V.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') || CASE WHEN V.ED_DT IS NOT NULL AND V.ED_DT != V.ST_DT THEN '~' || TO_CHAR(TO_DATE(V.ED_DT, 'YYYYMMDD'), 'MM-DD') ELSE '' END || ' (' || NVL(C.CODE_NM, V.VAC_TYPE_CD) || ' ' || V.DEDUCT_DAYS || '일)' ELSE NULL END, '; ' ) WITHIN GROUP (ORDER BY V.ST_DT ASC) AS VAC_ANNUAL_INFO_LIST,
/* 2. 근무대체 전용 이력 */ LISTAGG( CASE WHEN V.VAC_TYPE_CD IN ('PM07TYPE11','PM07TYPE12') THEN TO_CHAR(TO_DATE(V.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') || CASE WHEN V.ED_DT IS NOT NULL AND V.ED_DT != V.ST_DT THEN '~' || TO_CHAR(TO_DATE(V.ED_DT, 'YYYYMMDD'), 'MM-DD') ELSE '' END || ' (' || NVL(C.CODE_NM, V.VAC_TYPE_CD) || ' ' || V.DEDUCT_DAYS || '일)' ELSE NULL END, '; ' ) WITHIN GROUP (ORDER BY V.ST_DT ASC) AS VAC_WORK_SUBST_INFO_LIST,
/* 3. 하계휴가대체 전용 이력 */ LISTAGG( CASE WHEN V.VAC_TYPE_CD = 'PM07TYPE09' THEN TO_CHAR(TO_DATE(V.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') || CASE WHEN V.ED_DT IS NOT NULL AND V.ED_DT != V.ST_DT THEN '~' || TO_CHAR(TO_DATE(V.ED_DT, 'YYYYMMDD'), 'MM-DD') ELSE '' END || ' (' || NVL(C.CODE_NM, V.VAC_TYPE_CD) || ' ' || V.DEDUCT_DAYS || '일)' ELSE NULL END, '; ' ) WITHIN GROUP (ORDER BY V.ST_DT ASC) AS VAC_SUMMER_INFO_LIST,
LISTAGG( TO_CHAR(TO_DATE(V.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') || CASE WHEN V.ED_DT IS NOT NULL AND V.ED_DT != V.ST_DT THEN '~' || TO_CHAR(TO_DATE(V.ED_DT, 'YYYYMMDD'), 'MM-DD') ELSE '' END || ' (' || NVL(C.CODE_NM, V.VAC_TYPE_CD) || ' ' || V.DEDUCT_DAYS || '일)', '; ' ) WITHIN GROUP (ORDER BY V.ST_DT ASC) AS VAC_INFO_LIST FROM TB_PM07M01 V LEFT JOIN TB_CM05M01 C ON V.VAC_TYPE_CD = C.CODE_ID WHERE V.SANCTN_STS = 'END'
AND V.ST_DT LIKE #{yy} || '%'
GROUP BY V.CO_CD, V.REQ_ID ) VS ON VS.CO_CD = M.CO_CD AND VS.REQ_ID = M.USER_ID WHERE 1=1
AND M.YY = #{yy}
AND M.USER_ID = #{userId}
AND (U.NAME LIKE '%' || #{searchValue} || '%' OR M.USER_ID LIKE '%' || #{searchValue} || '%')
AND ( U.USE_YN = 'Y' OR ( NVL(U.USE_YN, 'N') = 'N' AND U.LEAVE_DT IS NOT NULL AND SUBSTR(REGEXP_REPLACE(TO_CHAR(U.LEAVE_DT), '[^0-9]', ''), 1, 4) = #{yy} ) )
AND U.USE_YN = 'Y'
) T ORDER BY T.YY DESC, T.DEPT_SORT_NO ASC, T.DEPT_NM ASC, T.USER_NM ASC


