UPDATE TB_PM07M03
SET WORK_RPT_NO = #{workRptNo, jdbcType=VARCHAR}
WHERE CO_CD = #{coCd, jdbcType=VARCHAR}
  AND REQ_NO = #{reqNo, jdbcType=VARCHAR}
  AND VAC_DT = #{vacDt, jdbcType=VARCHAR}

mapper.select:


SELECT
	REQ_NO,
	REQ_TITL,
	TO_CHAR(TO_DATE(ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT,
	TO_CHAR(TO_DATE(ED_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT,
	TO_CHAR(TO_DATE(NVL(NULLIF(ST_TM, ''), '0000'), 'HH24MI'), 'HH24:MI') AS ST_TM,
	TO_CHAR(TO_DATE(NVL(NULLIF(ED_TM, ''), '2359'), 'HH24MI'), 'HH24:MI') AS ED_TM,
	(SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = VAC_TYPE_CD) AS VAC_TYPE_NM
FROM TB_PM07M01
WHERE REQ_ID = #{reqId}
  AND ST_DT <= #{edDt}
  AND ED_DT >= #{stDt}
  AND NVL(NULLIF(ST_TM, ''), '0000') < #{edTm}
  AND NVL(NULLIF(ED_TM, ''), '2359') > #{stTm}

  AND REQ_NO != #{reqNo}

ORDER BY ST_DT ASC
